    for (Interest interest : interestRepository.findAllByProductColorId(productColor.getId())) {
        User user = interest.getUser();
        if (user.getId().equals(saleBid.getSeller().getId()) || !user.isActive()) {
            continue;
        }
        notificationCommandService.createNotification(
                user.getId(),
                NotificationCategory.SHOPPING,
                NotificationType.FAVORITE,
                message
        );
    }
}

